def min_add_to_make_valid(s: str) -> int:
    prev = 0
    stack = []
    result = 0
    for char in s:
        if not stack and char == ")":
            result += 1
        elif char == "(" and prev == 0:
            stack.append(1)
        elif char == "(" and prev == "(":
            stack.append(stack.pop()+1)
        elif char == "(" and prev == ")":
            stack.append(1)
        elif char == ")" and stack:
            tmp = stack.pop()-1
            if tmp!=0:
                stack.append(tmp)
        elif char == ")" and not stack:
            result+=1
        prev = char
    for elem in stack:
        result += abs(elem)
    return result

def findIslands(grid):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    islands = 0

    def dfs(grid, r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != 1:
            return
        grid[r][c] = -1  # Mark as visited
        dfs(grid, r+1, c)
        dfs(grid, r-1, c)
        dfs(grid, r, c+1)
        dfs(grid, r, c-1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dfs(grid, r, c)
                islands += 1

    return islands

def is_one_edit_away(s1, s2):
    len_diff = abs(len(s1) - len(s2))
    if len_diff > 1:
        return False
    elif len_diff == 0:
        diff_count = 0
        for i in range(len(s1)):
            if s1[i] != s2[i]:
                diff_count += 1
        return diff_count == 1
    elif len(s1) > len(s2):
        return one_insert_edit_away(s1, s2)
    else:
        return one_insert_edit_away(s2, s1)

def one_insert_edit_away(s1, s2):
    i = j = 0
    while i < len(s1) and j < len(s2):
        if s1[i] != s2[j]:
            if i != j:
                return False
            i += 1
        else:
            i += 1
            j += 1
    return True

