def is_postorder_bst(postorder):
    def helper(i, j):
        if i >= j:
            return True
        parent = i
        while parent < j and postorder[parent] < postorder[j]:
            parent += 1
        mid = parent
        while parent < j and postorder[parent] > postorder[j]:
            parent += 1
        return parent == j and helper(i, mid - 1) and helper(mid, j - 1)

    return helper(0, len(postorder) - 1)

from typing import List


def binary_search_first(arr: List[int], target: int) -> int:
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            if mid == 0 or arr[mid-1] < target:
                return mid
            else:
                right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1


def binary_search_last(arr: List[int], target: int) -> int:
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            if mid == len(arr) - 1 or arr[mid+1] > target:
                return mid
            else:
                left = mid + 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1


def count_value_occurrence(arr: List[int], target: int) -> int:
    first_index = binary_search_first(arr, target)
    if first_index == -1:
        return 0
    last_index = binary_search_last(arr, target)
    return last_index - first_index + 1

def reverseOnlyLetters(S):
    S = list(S)
    left, right = 0, len(S) - 1
    while left < right:
        while left < right and not S[left].isalpha():
            left += 1
        while left < right and not S[right].isalpha():
            right -= 1
        S[left], S[right] = S[right], S[left]
        left, right = left + 1, right - 1
    return "".join(S)

def rotate_cipher(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            ascii_offset = ord('a') if char.islower() else ord('A')
            result += chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
        else:
            result += char
    return result

