def isPossibleDivide(nums: list[int], k: int) -> bool:
    if len(nums) % k != 0:
        return False

    counts = {}
    for n in nums:
        counts[n] = counts.get(n, 0) + 1

    uniques = sorted(list(set(nums)))

    while counts:
        chunk = []
        i = len(uniques) - 1
        while len(chunk) < k and i >= 0:
            next = uniques[i]
            if not chunk or next == chunk[-1] - 1:
                chunk.append(next)
                counts[next] -= 1
                if counts[next] <= 0:
                    del counts[next]
                    uniques.pop(i)
                i -= 1
            elif next == chunk[-1]:
                i -= 1
            else:
                return False
        if len(chunk) != k:
            return False
    return True

import math

def doCirclesIntersect(center1, radius1, center2, radius2):
    # calculate the distance between the two centers
    distance = math.sqrt((center1[0] - center2[0]) ** 2 + (center1[1] - center2[1]) ** 2)

    # if the sum of the radii is greater than the distance, the circles intersect
    return distance < (radius1 + radius2)

