    for _ in range(3 - length):
        answer += answer[length-1]

    return answer

from collections import defaultdict

def is_unique_word_abbreviation(dictionary, word):
    dic = defaultdict(list)
    for w in dictionary:
        dic[word_abbr(w)].append(w)
    if word_abbr(word) not in dic:
        return True
    elif len(dic[word_abbr(word)]) == 1 and dic[word_abbr(word)][0] == word:
        return True
    else:
        return False

def word_abbr(word):
    if len(word) < 3:
        return word
    else:
        return word[0] + str(len(word) - 2) + word[-1]

def repeatedSubstringPattern(s: str) -> bool:
    for i in range(1, len(s)//2 + 1):
        if len(s) % i == 0:
            substring = s[:i]
            if substring * (len(s) // i) == s:
                return True
    return False

import random

def quickSelect_kthSmallest(arr, k):
    if k > 0 and k <= len(arr):
        pos = random_partition(arr, 0, len(arr) - 1)
        if pos == k - 1:
            return arr[pos]
        elif pos > k - 1:
            return quickSelect_kthSmallest(arr[:pos], k)
        else:
            return quickSelect_kthSmallest(arr[pos + 1:], k - pos - 1)

def random_partition(arr, left, right):
    pivot_index = random.randint(left, right)
    arr[pivot_index], arr[right] = arr[right], arr[pivot_index]
    return partition(arr, left, right)

def partition(arr, left, right):
    pivot = arr[right]
    i = left - 1
    for j in range(left, right):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[right] = arr[right], arr[i + 1]
    return i + 1

