    max_length = 0
    current_length = 0
    found_one = False
    for bit in binary:
        if bit == '1':
            if found_one and current_length > max_length:
                max_length = current_length
            current_length = 0
            found_one = True
        elif found_one:
            current_length += 1
    return max_length

