from collections import defaultdict

def max_points_on_same_line(points):
    """
    This function finds the maximum number of points that lie on the same line from a list of points in a 2D plane.
    """
    def gcd(x, y):
        while y != 0:
            x, y = y, x % y
        return x

    if len(points) <= 2:
        return len(points)

    max_points = 0
    for i in range(len(points)):
        point1 = points[i]
        slope_count = defaultdict(int)
        same_points = 1
        for j in range(i+1, len(points)):
            point2 = points[j]
            if point1[0] == point2[0] and point1[1] == point2[1]:
                same_points += 1
                continue
            if point1[0] == point2[0]:
                slope = float('inf')
            else:
                # Calculate the slope using rise/run and reduce it to the lowest terms using gcd
                rise = point2[1] - point1[1]
                run = point2[0] - point1[0]
                gcd_val = gcd(rise, run)
                slope = (rise // gcd_val, run // gcd_val)
            slope_count[slope] += 1
            max_points = max(max_points, slope_count[slope] + same_points)
        max_points = max(max_points, same_points)

    return max_points

