    curr_count = {}

    for j in range(len(s)):
        curr_count[s[j]] = curr_count.get(s[j], 0) + 1

        if s[j] in pat_count and curr_count[s[j]] <= pat_count[s[j]]:
            count += 1

        if count == len(pat):
            while curr_count[s[start]] > pat_count.get(s[start], 0):
                if curr_count[s[start]] > 0:
                    curr_count[s[start]] -= 1
                start += 1

            window_len = j - start + 1
