def find_num_in_rotated_array(nums, target):
    def find_rotate_index(left, right):
        if nums[left] < nums[right]:
            return 0

        while left <= right:
            pivot = (left + right) // 2
            if nums[pivot] > nums[pivot + 1]:
                return pivot + 1
            else:
                if nums[pivot] < nums[left]:
                    right = pivot - 1
                else:
                    left = pivot + 1

    def binary_search(left, right):
        while left <= right:
            pivot = (left + right) // 2
            if nums[pivot] == target:
                return True
            else:
                if target < nums[pivot]:
                    right = pivot - 1
                else:
                    left = pivot + 1
        return False

    def count_appearances(left, right):
        count = 0
        while left <= right:
            if nums[left] == target:
                count += 1
            left += 1
        return count

    n = len(nums)
    if n == 0:
        return 0

    rotate_index = find_rotate_index(0, n - 1)

    if nums[rotate_index] == target:
        count = count_appearances(rotate_index, n - 1)
        if rotate_index > 0 and nums[0] == target:
            count += count_appearances(0, rotate_index - 1)
        return count

    if rotate_index == 0:
        return count_appearances(0, n - 1)

    if target < nums[0]:
        return count_appearances(rotate_index, n - 1)

    return count_appearances(0, rotate_index - 1)

