    missing = len(T)
    start, minStart = 0, 0
    minLen = float('inf')
    for end, char in enumerate(S):
        if need[char] > 0:
            missing -= 1
        need[char] -= 1

        while missing == 0:
            if end - start < minLen:
                minLen = end - start
                minStart = start

            need[S[start]] += 1
            if need[S[start]] > 0:
                missing += 1
            start += 1

    if minLen != float('inf'):
        return S[minStart:minStart+minLen+1]
    return ''

