    partition = Partition()
    return partition.canPartition(nums)

from collections import defaultdict

def find_smallest_set_of_vertices(n, edges):
    incoming_node = defaultdict(list)
    for x, y in edges:
        incoming_node[y].append(x)
    res = []
    for i in range(n):
        if not incoming_node[i]:
            res.append(i)
    return res

def smallest_perimeter(area):
    import math
    for i in range(int(math.sqrt(area)), 0, -1):
        if area % i == 0:
            return 2 * (i + area // i)

print(smallest_perimeter(12))  # Output: 14
print(smallest_perimeter(30))  # Output: 22
print(smallest_perimeter(100))  # Output: 40

def power_modulo(base, exponent, module):
    if exponent == 0:
        return 1
    t = power_modulo(base, exponent//2, module) % module
    t = (t*t) % module
    if exponent % 2 == 0:
        return t
    else:
        return ((base % module) * t) % module

def max_subarray_sum_of_size_k(arr, k):
    if len(arr) < k:
        return -1
    window_sum = sum(arr[:k])
    max_sum = window_sum
    for i in range(len(arr) - k):
        window_sum = window_sum - arr[i] + arr[i+k]
        max_sum = max(max_sum, window_sum)
    return max_sum

def max_depth_of_dict(d):
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(max_depth_of_dict(d[k]) for k in d)

# Test cases
print(max_depth_of_dict({'a': 1, 'b': {'c': 2, 'd': {'e': 3}}}) == 3)
print(max_depth_of_dict({'a': {'b': {'c': {'d': 1}}}}) == 4)
print(max_depth_of_dict({'a': 1, 'b': 2, 'c': 3}) == 1)

import heapq

def reorganizeString(S):
    """
    :type S: str
    :rtype: str
    """
    hashmap = {}
    for c in S:
        hashmap[c] = hashmap.get(c, 0) + 1
    heap = []
    for c, freq in hashmap.items():
        heapq.heappush(heap, [-freq, c])
    res = ''
    while heap:
        freq1, c1 = heapq.heappop(heap)
        if res and res[-1] == c1:
            return ''
        res += c1
        if heap:
            freq2, c2 = heapq.heappop(heap)
            res += c2
            if freq2 + 1 < 0:
                heapq.heappush(heap, [freq2 + 1, c2])
        if freq1 + 1 < 0:
            heapq.heappush(heap, [freq1 + 1, c1])
    return ''.join(res)

# Test cases
assert reorganizeString("vvvlo") == "vlvov"
assert reorganizeString("aab") == "aba"
assert reorganizeString("aaab") == ""

def check_balanced_parentheses(s: str) -> bool:
    stack = []
    bracket_map = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

def max_len(arr):
    max_length = 0
    count = 0
    sum_dict = {0: -1}
    for i in range(len(arr)):
        if arr[i] == 0:
            count -= 1
        else:
            count += 1
        if count in sum_dict:
            max_length = max(max_length, i - sum_dict[count])
        else:
            sum_dict[count] = i
    return max_length

def is_palindrome_permutation(s):
    s = s.replace(' ', '').lower()
    d = dict()
    for char in s:
        if char in d:
            d[char] += 1
        else:
            d[char] = 1
    odd_count = 0
    for count in d.values():
        if count % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False
    return True

def average_temperature(temperatures):
    ans = []
    for day in temperatures:
        ans.append(sum(day) / len(day))
    return ans

def smallest_largest_digits(num):
    num = str(abs(num))
    smallest = min(int(digit) for digit in num)
    largest = max(int(digit) for digit in num)
    return (smallest, largest)

def top_k_largest(arr, k):
    arr.sort(reverse=True)
    return arr[:k]

def minCoinChange(coins, amount):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0

    for a in range(1, amount + 1):
        for c in coins:
            if a - c >= 0:
                dp[a] = min(dp[a], 1 + dp[a - c])

    if dp[amount] != amount + 1 :
        return dp[amount]
    else :
        return -1

import re

def validate_password(password):
    if len(password) < 8:
        return False
    elif not re.search("[a-zA-Z]", password):
        return False
    elif not re.search("[0-9]", password):
        return False
    elif not re.search("[!@#$%^&*]", password):
        return False
    else:
        return True

def bubble_sort_desc(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] < arr[j+1] :
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

from collections import Counter

def k_diff_pairs(nums, k):
    if None in (nums, k):
        return None
    c = Counter(nums)
    result = 0
    for i in c:
        if (k > 0 and i + k in c) or (k == 0 and c[i] > 1):
            result += 1
    return result

def alphabetic_count(s):
    count = 0
    for char in s:
        if char.isalpha():
            count += 1
    return count

def reverse_and_move_digits(strings):
    result = []
    for s in strings:
        digits = ""
        letters = ""
        for char in s:
            if char.isdigit():
                digits += char
            else:
                letters += char
        result.append(letters[::-1] + digits[::-1])
    return result

def sign_list(numbers):
    signs = []
    for number in numbers:
        if number > 0:
            signs.append('+')
        elif number < 0:
            signs.append('-')
        else:
            signs.append('0')
    return signs
